-- LOCAL-ONLY executable design. NOT a registered migration or production installer.
-- Creates fresh roles; collision fails. No passwords, role memberships,
-- authenticator grants, rollout activation, mail or business-data mutation.
-- The NOLOGIN executor needs BYPASSRLS because private tables FORCE RLS with
-- no policies. It cannot log in or create roles, and owns no business tables.
-- The runtime role receives ONLY this fixed dispatcher, not executor membership.
BEGIN;
CREATE ROLE faolla_checkout_runtime NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS NOREPLICATION;
CREATE ROLE faolla_checkout_executor NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE BYPASSRLS NOREPLICATION;
GRANT USAGE ON SCHEMA public TO faolla_checkout_runtime,faolla_checkout_executor;
GRANT USAGE ON SCHEMA faolla_checkout_design TO faolla_checkout_executor;
GRANT SELECT ON faolla_checkout_design.offer_versions,faolla_checkout_design.offer_heads,faolla_checkout_design.settlements,faolla_checkout_design.facts,faolla_checkout_design.catalog_versions,faolla_checkout_design.catalog_heads,faolla_checkout_design.bundle_pilots,faolla_checkout_design.bundle_results,faolla_checkout_design.bundle_cancellations,faolla_checkout_design.bundle_coupon_returns,faolla_checkout_design.merchant_cancellation_actors,faolla_checkout_design.on_site_collections,faolla_checkout_design.cart_quote_pilots,faolla_checkout_design.cart_collection_pilots,faolla_checkout_design.cart_collections,faolla_checkout_design.cart_submission_pilots,faolla_checkout_design.intent_pilots,faolla_checkout_design.intent_claims,faolla_checkout_design.intent_acknowledgements,faolla_checkout_design.retained_intent_registrations,faolla_checkout_design.unused_reference_pilots,faolla_checkout_design.closed_unused_references,faolla_checkout_design.original_service_pilots TO faolla_checkout_executor;
