GRANT INSERT,UPDATE ON faolla_checkout_design.catalog_heads,faolla_checkout_design.offer_heads TO faolla_checkout_executor;
-- Row locking requires UPDATE privilege, even though no enabled flag is written.
GRANT UPDATE(enabled) ON faolla_checkout_design.bundle_pilots TO faolla_checkout_executor;
GRANT UPDATE(enabled) ON faolla_checkout_design.intent_pilots TO faolla_checkout_executor;
GRANT UPDATE(enabled) ON faolla_checkout_design.cart_quote_pilots TO faolla_checkout_executor;
GRANT UPDATE(enabled) ON faolla_checkout_design.cart_submission_pilots TO faolla_checkout_executor;
GRANT UPDATE(enabled) ON faolla_checkout_design.cart_collection_pilots TO faolla_checkout_executor;
GRANT UPDATE(enabled) ON faolla_checkout_design.unused_reference_pilots TO faolla_checkout_executor;
GRANT UPDATE(enabled) ON faolla_checkout_design.original_service_pilots TO faolla_checkout_executor;
GRANT SELECT,UPDATE(id) ON public.pages TO faolla_checkout_executor;
GRANT SELECT,UPDATE(singleton) ON public.faolla_booking_atomic_control TO faolla_checkout_executor;
GRANT SELECT ON public.faolla_booking_atomic_commands TO faolla_checkout_executor;
