.faolla_member_checkout_reporting_v2(text,jsonb),public.faolla_member_checkout_reporting_v3(text,jsonb),public.faolla_member_checkout_result_v2(text,text,text),public.faolla_member_checkout_retained_intent_review_v1(text,text,text),public.faolla_member_checkout_submission_commit_v2(text,text,text,text,jsonb,jsonb,text),public.faolla_member_checkout_submission_snapshot_v2(text,text,text,text,text),public.faolla_member_checkout_unused_reference_review_v1(text,text,text) TO faolla_checkout_executor;
CREATE FUNCTION public.faolla_checkout_runtime_v1(p_function text,p_arguments jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE allowed text[];
BEGIN
 IF p_function IS NULL OR jsonb_typeof(p_arguments) IS DISTINCT FROM 'object'
   OR octet_length(p_arguments::text)>33554432 THEN RAISE EXCEPTION 'checkout_runtime_invalid_request';END IF;
 CASE p_function
  WHEN 'faolla_member_checkout_catalog_snapshot_v1' THEN allowed:=ARRAY['p_site_id']::text[];
  WHEN 'faolla_member_checkout_catalog_save_v1' THEN allowed:=ARRAY['p_site_id','p_expected_version','p_next_version','p_actor_key','p_offer']::text[];
  WHEN 'faolla_member_checkout_result_v2' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_cancel_v2' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_expected_updated_at']::text[];
  WHEN 'faolla_checkout_resource_link_v1' THEN allowed:=ARRAY['p_site_id','p_kind','p_id','p_principal_key']::text[];
  WHEN 'faolla_checkout_merchant_cancel_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_actor_key','p_expected_updated_at']::text[];
  WHEN 'faolla_member_checkout_on_site_result_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_on_site_cancel_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_expected_updated_at']::text[];
  WHEN 'faolla_checkout_on_site_merchant_cancel_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_actor_key','p_expected_updated_at']::text[];
  WHEN 'faolla_member_checkout_submission_snapshot_v2' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_request_hash','p_offer_id']::text[];
  WHEN 'faolla_member_checkout_submission_commit_v2' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_request_hash','p_snapshot','p_plan','p_not_after']::text[];
  WHEN 'faolla_member_checkout_on_site_snapshot_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_request_hash','p_offer_id']::text[];
  WHEN 'faolla_member_checkout_on_site_commit_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_request_hash','p_snapshot','p_plan','p_not_after']::text[];
  WHEN 'faolla_member_checkout_reporting_v1' THEN allowed:=ARRAY['p_site_id','p_resources']::text[];
  WHEN 'faolla_member_checkout_original_result_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_reporting_v2' THEN allowed:=ARRAY['p_site_id','p_resources']::text[];
  WHEN 'faolla_member_checkout_original_resource_v1' THEN allowed:=ARRAY['p_site_id','p_kind','p_id','p_principal_key']::text[];
  WHEN 'faolla_checkout_on_site_collect_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_actor_key','p_expected_updated_at','p_expected_due_minor','p_not_after']::text[];
  WHEN 'faolla_checkout_resource_link_v2' THEN allowed:=ARRAY['p_site_id','p_kind','p_id','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_cart_quote_snapshot_v1' THEN allowed:=ARRAY['p_site_id','p_principal_key','p_request_hash','p_offer_ids']::text[];
  WHEN 'faolla_checkout_cart_collect_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_actor_key','p_expected_updated_at','p_expected_due_minor','p_not_after']::text[];
  WHEN 'faolla_checkout_cart_collection_read_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key']::text[];
  WHEN 'faolla_member_checkout_cart_result_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_cart_submission_snapshot_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_request_hash','p_quote_request_hash','p_offer_ids']::text[];
  WHEN 'faolla_member_checkout_cart_commit_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_request_hash','p_snapshot','p_plan','p_not_after']::text[];
  WHEN 'faolla_member_checkout_cart_cancel_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_expected_updated_at','p_not_after']::text[];
  WHEN 'faolla_member_checkout_reporting_v3' THEN allowed:=ARRAY['p_site_id','p_resources']::text[];
  WHEN 'faolla_member_checkout_original_resource_v2' THEN allowed:=ARRAY['p_site_id','p_kind','p_id','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_pending_intent_v1' THEN allowed:=ARRAY['p_site_id','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_acknowledge_intent_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_generation','p_review_hash','p_not_after']::text[];
  WHEN 'faolla_member_checkout_intent_review_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_intent_cart_commit_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_request_hash','p_snapshot','p_plan','p_not_after']::text[];
  WHEN 'faolla_member_checkout_history_original_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_legacy_review_v1' THEN allowed:=ARRAY['p_site_id','p_block_id','p_request_id','p_principal_key','p_not_after']::text[];
  WHEN 'faolla_member_checkout_retained_intent_review_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_register_retained_intent_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_review_hash','p_not_after']::text[];
  WHEN 'faolla_member_checkout_history_inventory_v1' THEN allowed:=ARRAY['p_site_id','p_principal_key','p_after']::text[];
  WHEN 'faolla_checkout_legacy_order_commit_v1' THEN allowed:=ARRAY['p_site_id','p_mutation','p_not_after']::text[];
  WHEN 'faolla_checkout_legacy_booking_commit_v1' THEN allowed:=ARRAY['p_site_id','p_command_key','p_request_hash','p_mutation','p_not_after']::text[];
  WHEN 'faolla_checkout_cart_resource_link_v1' THEN allowed:=ARRAY['p_site_id','p_id']::text[];
  WHEN 'faolla_checkout_cart_merchant_cancel_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_actor_key','p_expected_updated_at','p_not_after']::text[];
  WHEN 'faolla_member_checkout_unused_reference_review_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_close_unused_reference_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_review_hash','p_not_after']::text[];
  WHEN 'faolla_member_checkout_original_service_review_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key']::text[];
  WHEN 'faolla_member_checkout_original_service_cancel_v1' THEN allowed:=ARRAY['p_site_id','p_operation_key','p_principal_key','p_review_hash','p_expected_updated_at','p_not_after']::text[];
  WHEN 'faolla_checkout_cart_personal_resource_link_v1' THEN allowed:=ARRAY['p_site_id','p_id','p_principal_key']::text[];
  ELSE RAISE EXCEPTION 'checkout_runtime_forbidden';
 END CASE;
 IF NOT (p_arguments ?& allowed) OR (SELECT count(*) FROM jsonb_object_keys(p_arguments))<>cardinality(allowed)
   THEN RAISE EXCEPTION 'checkout_runtime_invalid_request';END IF;
 CASE p_function
  WHEN 'faolla_member_checkout_catalog_snapshot_v1' THEN RETURN public.faolla_member_checkout_catalog_snapshot_v1((p_arguments->>'p_site_id')::text);
  WHEN 'faolla_member_checkout_catalog_save_v1' THEN RETURN public.faolla_member_checkout_catalog_save_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_expected_version')::uuid,(p_arguments->>'p_next_version')::uuid,(p_arguments->>'p_actor_key')::text,(p_arguments->'p_offer'));
  WHEN 'faolla_member_checkout_result_v2' THEN RETURN public.faolla_member_checkout_result_v2((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_principal_key')::text);
  WHEN 'faolla_member_checkout_cancel_v2' THEN RETURN public.faolla_member_checkout_cancel_v2((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_principal_key')::text,(p_arguments->>'p_expected_updated_at')::text);
  WHEN 'faolla_checkout_resource_link_v1' THEN RETURN public.faolla_checkout_resource_link_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_kind')::text,(p_arguments->>'p_id')::text,(p_arguments->>'p_principal_key')::text);
  WHEN 'faolla_checkout_merchant_cancel_v1' THEN RETURN public.faolla_checkout_merchant_cancel_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_actor_key')::text,(p_arguments->>'p_expected_updated_at')::text);
  WHEN 'faolla_member_checkout_on_site_result_v1' THEN RETURN public.faolla_member_checkout_on_site_result_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_principal_key')::text);
  WHEN 'faolla_member_checkout_on_site_cancel_v1' THEN RETURN public.faolla_member_checkout_on_site_cancel_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_principal_key')::text,(p_arguments->>'p_expected_updated_at')::text);
  WHEN 'faolla_checkout_on_site_merchant_cancel_v1' THEN RETURN public.faolla_checkout_on_site_merchant_cancel_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_actor_key')::text,(p_arguments->>'p_expected_updated_at')::text);
  WHEN 'faolla_member_checkout_submission_snapshot_v2' THEN RETURN public.faolla_member_checkout_submission_snapshot_v2((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_principal_key')::text,(p_arguments->>'p_request_hash')::text,(p_arguments->>'p_offer_id')::text);
  WHEN 'faolla_member_checkout_submission_commit_v2' THEN RETURN public.faolla_member_checkout_submission_commit_v2((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_principal_key')::text,(p_arguments->>'p_request_hash')::text,(p_arguments->'p_snapshot'),(p_arguments->'p_plan'),(p_arguments->>'p_not_after')::text);
  WHEN 'faolla_member_checkout_on_site_snapshot_v1' THEN RETURN public.faolla_member_checkout_on_site_snapshot_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_principal_key')::text,(p_arguments->>'p_request_hash')::text,(p_arguments->>'p_offer_id')::text);
