  WHEN 'faolla_member_checkout_reporting_v1' THEN RETURN public.faolla_member_checkout_reporting_v1((p_arguments->>'p_site_id')::text,(p_arguments->'p_resources'));
  WHEN 'faolla_member_checkout_original_result_v1' THEN RETURN public.faolla_member_checkout_original_result_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_principal_key')::text);
  WHEN 'faolla_member_checkout_reporting_v2' THEN RETURN public.faolla_member_checkout_reporting_v2((p_arguments->>'p_site_id')::text,(p_arguments->'p_resources'));
  WHEN 'faolla_member_checkout_original_resource_v1' THEN RETURN public.faolla_member_checkout_original_resource_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_kind')::text,(p_arguments->>'p_id')::text,(p_arguments->>'p_principal_key')::text);
  WHEN 'faolla_checkout_on_site_collect_v1' THEN RETURN public.faolla_checkout_on_site_collect_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_operation_key')::text,(p_arguments->>'p_actor_key')::text,(p_arguments->>'p_expected_updated_at')::text,(p_arguments->>'p_expected_due_minor')::bigint,(p_arguments->>'p_not_after')::timestamptz);
  WHEN 'faolla_checkout_resource_link_v2' THEN RETURN public.faolla_checkout_resource_link_v2((p_arguments->>'p_site_id')::text,(p_arguments->>'p_kind')::text,(p_arguments->>'p_id')::text,(p_arguments->>'p_principal_key')::text);
  WHEN 'faolla_member_checkout_cart_quote_snapshot_v1' THEN RETURN public.faolla_member_checkout_cart_quote_snapshot_v1((p_arguments->>'p_site_id')::text,(p_arguments->>'p_principal_key')::text,(p_arguments->>'p_request_hash')::text,(p_arguments->'p_offer_ids'));
